package network

import (
	"net"
	"strings"
)

// This file has no build tag on purpose: the macOS adapter classification is
// pure logic over net.Interface values, so its table tests run on every OS
// (including the Windows CI runner). Only adapters_darwin.go wires it in.

// macVirtualInterfacePrefixes are BSD interface-name prefixes that never
// identify the physical network a Mac is on. Unlike Windows adapter names,
// macOS names are generated by the kernel and can't be renamed by the user,
// so a prefix match is a real classification, not a heuristic:
//
//   - utun, ipsec, ppp: VPN and tunnel endpoints (WireGuard, Tailscale,
//     corporate IKEv2/L2TP). Their address says where the VPN hands out
//     addresses, not where the machine is.
//   - awdl, llw: Apple Wireless Direct Link and low-latency WLAN, the
//     AirDrop/Continuity peer-to-peer links.
//   - bridge: Internet Sharing and virtual-machine bridges (bridge100 and
//     up), plus the Thunderbolt Bridge.
//   - vmenet, vmnet, vnic: Virtualization.framework, VMware and Parallels
//     host networks — the same private subnet on every machine with the
//     hypervisor installed.
//   - gif, stf: generic IP-in-IP and 6to4 tunnels.
//   - anpi: Apple's internal network-processor interfaces on Apple silicon.
//   - ap: the Wi-Fi access-point interface used by Personal Hotspot.
//   - lo: loopback.
//
// Physical Ethernet and Wi-Fi are always en<N>, so nothing here can shadow
// them.
var macVirtualInterfacePrefixes = []string{
	"utun", "ipsec", "ppp",
	"awdl", "llw",
	"bridge",
	"vmenet", "vmnet", "vnic",
	"gif", "stf",
	"anpi",
	"ap",
	"lo",
}

// isMacVirtualInterfaceName reports whether a macOS interface name belongs
// to one of the virtual families in macVirtualInterfacePrefixes.
func isMacVirtualInterfaceName(name string) bool {
	name = strings.ToLower(name)
	for _, prefix := range macVirtualInterfacePrefixes {
		if strings.HasPrefix(name, prefix) {
			return true
		}
	}
	return false
}

// macAdapterAllowed is the darwin adapterAllowed predicate: an interface
// counts as evidence of the physical network only if it is up, broadcast
// capable (real Ethernet and Wi-Fi are; tunnels are not), not point-to-point
// or loopback, and not a known virtual family by name.
//
// The flag checks catch tunnels a VPN product names unconventionally; the
// name check catches virtual interfaces that do look like Ethernet (bridges,
// hypervisor networks, AWDL). Both are needed.
func macAdapterAllowed(iface net.Interface) bool {
	if iface.Flags&net.FlagUp == 0 || iface.Flags&net.FlagBroadcast == 0 {
		return false
	}
	if iface.Flags&(net.FlagPointToPoint|net.FlagLoopback) != 0 {
		return false
	}
	return !isMacVirtualInterfaceName(iface.Name)
}
